/* Graphite Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="graphite-light"] {
  --background: hsl(300 0% 94.75%);
  --foreground: hsl(0 0% 19.89%);
  --card: hsl(300 0% 96.06%);
  --card-foreground: hsl(0 0% 19.89%);
  --popover: hsl(300 0% 96.06%);
  --popover-foreground: hsl(0 0% 19.89%);
  --primary: hsl(0 0% 37.75%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(0 0% 88.27%);
  --secondary-foreground: hsl(0 0% 19.89%);
  --muted: hsl(340 0% 85.7%);
  --muted-foreground: hsl(300 0% 39.97%);
  --accent: hsl(320 0% 75.57%);
  --accent-foreground: hsl(0 0% 19.89%);
  --destructive: hsl(0.01 60.12% 50.08%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(320 0% 81.87%);
  --input: hsl(0 0% 88.27%);
  --ring: hsl(0 0% 37.75%);
  --chart-1: hsl(0 0% 37.75%);
  --chart-2: hsl(180.08 20.2% 33.86%);
  --chart-3: hsl(330 0% 56.07%);
  --chart-4: hsl(0 0% 65.69%);
  --chart-5: hsl(320 0% 75.57%);
  --radius: 0.35rem;
  --sidebar: hsl(330 0% 92.15%);
  --sidebar-foreground: hsl(0 0% 19.89%);
  --sidebar-primary: hsl(0 0% 37.75%);
  --sidebar-primary-foreground: hsl(300 50% 100%);
  --sidebar-accent: hsl(320 0% 75.57%);
  --sidebar-accent-foreground: hsl(0 0% 19.89%);
  --sidebar-border: hsl(320 0% 81.87%);
  --sidebar-ring: hsl(0 0% 37.75%);
  --font-sans: Montserrat, sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: Fira Code, monospace;
  --shadow-color: hsl(340 0% 20% / 0.1);
  --shadow-opacity: 0.15;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 2px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 2px 0px 0px hsl(0 0% 20% / 0.07);
  --shadow-xs: 0px 2px 0px 0px hsl(0 0% 20% / 0.07);
  --shadow-sm:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 1px 2px -1px hsl(0 0% 20% / 0.15);
  --shadow:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 1px 2px -1px hsl(0 0% 20% / 0.15);
  --shadow-md:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 2px 4px -1px hsl(0 0% 20% / 0.15);
  --shadow-lg:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 4px 6px -1px hsl(0 0% 20% / 0.15);
  --shadow-xl:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 8px 10px -1px hsl(0 0% 20% / 0.15);
  --shadow-2xl: 0px 2px 0px 0px hsl(0 0% 20% / 0.38);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="graphite-dark"] {
  --background: hsl(300 0% 10.4%);
  --foreground: hsl(340 0% 85.7%);
  --card: hsl(330 0% 12.22%);
  --card-foreground: hsl(340 0% 85.7%);
  --popover: hsl(330 0% 12.22%);
  --popover-foreground: hsl(340 0% 85.7%);
  --primary: hsl(0 0% 63.26%);
  --primary-foreground: hsl(300 0% 10.4%);
  --secondary: hsl(320 0% 18.9%);
  --secondary-foreground: hsl(340 0% 85.7%);
  --muted: hsl(300 0% 16.95%);
  --muted-foreground: hsl(0 0% 50.21%);
  --accent: hsl(0 0% 24.94%);
  --accent-foreground: hsl(340 0% 85.7%);
  --destructive: hsl(0.14 65.17% 63.96%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(300 0% 20.89%);
  --input: hsl(320 0% 18.9%);
  --ring: hsl(0 0% 63.26%);
  --chart-1: hsl(0 0% 63.26%);
  --chart-2: hsl(187.06 13.39% 56.25%);
  --chart-3: hsl(0 0% 44.47%);
  --chart-4: hsl(0 0% 34.47%);
  --chart-5: hsl(0 0% 24.94%);
  --radius: 0.35rem;
  --sidebar: hsl(330 0% 12.22%);
  --sidebar-foreground: hsl(340 0% 85.7%);
  --sidebar-primary: hsl(0 0% 63.26%);
  --sidebar-primary-foreground: hsl(300 0% 10.4%);
  --sidebar-accent: hsl(0 0% 24.94%);
  --sidebar-accent-foreground: hsl(340 0% 85.7%);
  --sidebar-border: hsl(300 0% 20.89%);
  --sidebar-ring: hsl(0 0% 63.26%);
  --font-sans: Inter, sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: Fira Code, monospace;
  --shadow-color: hsl(340 0% 20% / 0.1);
  --shadow-opacity: 0.15;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 2px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 2px 0px 0px hsl(0 0% 20% / 0.07);
  --shadow-xs: 0px 2px 0px 0px hsl(0 0% 20% / 0.07);
  --shadow-sm:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 1px 2px -1px hsl(0 0% 20% / 0.15);
  --shadow:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 1px 2px -1px hsl(0 0% 20% / 0.15);
  --shadow-md:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 2px 4px -1px hsl(0 0% 20% / 0.15);
  --shadow-lg:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 4px 6px -1px hsl(0 0% 20% / 0.15);
  --shadow-xl:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 8px 10px -1px hsl(0 0% 20% / 0.15);
  --shadow-2xl: 0px 2px 0px 0px hsl(0 0% 20% / 0.38);
}
